    # C136 (2026-09-17): seed 精确文件名可能被某进程独占持有 (改名允许/写删被拒);
    #   改为「先改名旧 seed 再复制」—— 语义等价, 且不受锁影响 (第 64 站诊断, 见台账 §64)
     if (Test-Path qcc_zh_seed.exe) {
        $stamp = "qcc_zh_seed.exe.hold"
        Remove-Item $stamp -Force -ErrorAction SilentlyContinue
        # R355 (2026-09-25 虾米 · 审计岗递刀): **本 catch 原为空 —— 静默吞异常**。
        #   审计岗坐实: seed 曾「静默落后」三次（旧 seed 25D59B37 顶班）⟹ 之后所有以 seed 为链起点的
        #   验证都在验**旧编译器**, PASS 有假绿嫌疑（属 C18a「静默兜底」同型坑的复发）。
        #   现改为**响亮失败提示**但**不改控制流** —— 因为真正的兜底是紧随其后的「种子哈希校验」
        #   （`$seedH -ne $expected ⟹ FAIL exit 1`）: 改名失败 ⟹ Copy-Item 必失败或拷到旧物 ⟹ 校验必红。
        #   之所以不在此处直接 exit: C136 的现场是「改名允许 / 写删被拒」, 单一路径失败不足以断定全局失败,
        #   让校验做终裁可避免误杀「改名失败但 Copy 恰好成功」的合法情形。
        try { Rename-Item qcc_zh_seed.exe $stamp -ErrorAction Stop }
        catch {
            Write-Host "[警告 WARN] 旧 seed 改名失败（疑被进程独占）: $($_.Exception.Message)" -ForegroundColor Yellow
            Write-Host "            ⟹ 后续 seed 同步很可能失败; 若最终报「种子同步校验失败」, 请先结束占用 qcc_zh_seed.exe 的进程 (残留的 qcc_zh_*.exe 子编译器最常见)" -ForegroundColor Yellow
        }
    }
    Copy-Item $finalExe qcc_zh_seed.exe -Force
    $seedH = (Get-FileHash qcc_zh_seed.exe -Algorithm SHA256).Hash.Substring(0,8)
    if ($seedH -ne $expected) {
        Write-Host "[失败 FAIL] 种子同步校验失败: seed=$seedH 期望=$expected (exe 可能被占用; 请先 Move-Item 再 Copy-Item 重试)" -ForegroundColor Red
        exit 1
    }
    Write-Host "  [种子 seed] qcc_zh_seed.exe <- $finalExe (哈希校验 $seedH 通过; -NoSeed 可跳过)"
}

# ═══ 闸外检查 (第 262 站 ③ 根治后加入): 甲言 .obj 经 **gcc 链接** 后必须正常运行 ═══
#   为什么必须在链尾自动跑: 闸 (run_tests_zh.py) 只做「单文件 → 甲言编译 → 运行」;
#   而「内联库函数用 32 位寄存器承载 64 位指针」这类缺陷**只在 gcc/ld 链接时暴露** ——
#   甲言自己链自己基址低 (0x400000 量级), 32 位截断后恰好仍合法 ⟹ **闸永远测不出来**。
#   实测代价: 该缺陷潜伏 170+ 站, 直到启元建 jylib (甲言第一个库) 才现形 (0xC0000005)。
if (-not $NoSeed) {
    Write-Host "== 闸外检查: gcc 链接 (甲言 .obj + gcc driver) ==" -ForegroundColor Cyan
    powershell -NoProfile -ExecutionPolicy Bypass -File scripts\check_gcc_link.ps1
    if ($LASTEXITCODE -ne 0) {
        Write-Host "[失败 FAIL] 闸外检查 gcc 链接 未通过 —— 甲言 .obj 被 gcc 链接后不能正常运行" -ForegroundColor Red
        Write-Host "         (见 scripts\check_gcc_link.ps1 输出; 典型签名 = 内联库函数指针 32 位截断)" -ForegroundColor Red
        exit 1
    }
}
# ===== 入口刷新钩子（2026-09-25 虾米 · 审计岗建议 L3）=====
# 每站收尾自动刷新 _ATLAS_ENTRY.md + 14 表 ⟹ 「入口数字永远新鲜」。
# 只读统计、不改源码；失败不影响本脚本退出码。
try {
    $genEntry = Join-Path $PSScriptRoot '..\memory\atlas\tools\gen_entry.py'
    if (Test-Path $genEntry) {
        Write-Host '[入口刷新] python memory\atlas\tools\gen_entry.py' -ForegroundColor Cyan
        python $genEntry 2>&1 | Select-Object -Last 3
    } else {
        Write-Host '[入口刷新] 跳过（未找到 gen_entry.py）'
    }
} catch {
    Write-Host "[入口刷新] 失败（不影响验收）: $_"
}

exit 0

